    {dex = 70, species = "weepinbell", name = "WEEPINBELL", sourceName = "WEEPINBELL", category = "FLYCATCHER", heightFeet = 3, heightInches = 3, weightTenthsLb = 140, lines = {"It spits out", "POISONPOWDER to", "immobilize the", "", "enemy and then", "finishes it with", "a spray of ACID"}, sourceInternalId = 189, sourceEntry = "WeepinbellDexEntry"},
    {dex = 71, species = "victreebel", name = "VICTREEBEL", sourceName = "VICTREEBEL", category = "FLYCATCHER", heightFeet = 5, heightInches = 7, weightTenthsLb = 340, lines = {"Said to live in", "huge colonies", "deep in jungles,", "", "although no one", "has ever returned", "from there"}, sourceInternalId = 190, sourceEntry = "VictreebelDexEntry"},
    {dex = 72, species = "tentacool", name = "TENTACOOL", sourceName = "TENTACOOL", category = "JELLYFISH", heightFeet = 2, heightInches = 11, weightTenthsLb = 1000, lines = {"Drifts in shallow", "seas. Anglers who", "hook them by", "", "accident are", "often punished by", "its stinging acid"}, sourceInternalId = 24, sourceEntry = "TentacoolDexEntry"},
    {dex = 73, species = "tentacruel", name = "TENTACRUEL", sourceName = "TENTACRUEL", category = "JELLYFISH", heightFeet = 5, heightInches = 3, weightTenthsLb = 1210, lines = {"The tentacles are", "normally kept", "short. On hunts,", "", "they are extended", "to ensnare and", "immobilize prey"}, sourceInternalId = 155, sourceEntry = "TentacruelDexEntry"},
    {dex = 74, species = "geodude", name = "GEODUDE", sourceName = "GEODUDE", category = "ROCK", heightFeet = 1, heightInches = 4, weightTenthsLb = 440, lines = {"Found in fields", "and mountains.", "Mistaking them", "", "for boulders,", "people often step", "or trip on them"}, sourceInternalId = 169, sourceEntry = "GeodudeDexEntry"},
    {dex = 75, species = "graveler", name = "GRAVELER", sourceName = "GRAVELER", category = "ROCK", heightFeet = 3, heightInches = 3, weightTenthsLb = 2320, lines = {"Rolls down slopes", "to move. It rolls", "over any obstacle", "", "without slowing", "or changing its", "direction"}, sourceInternalId = 39, sourceEntry = "GravelerDexEntry"},
    {dex = 76, species = "golem", name = "GOLEM", sourceName = "GOLEM", category = "MEGATON", heightFeet = 4, heightInches = 7, weightTenthsLb = 6620, lines = {"Its boulder-like", "body is extremely", "hard. It can", "", "easily withstand", "dynamite blasts", "without damage"}, sourceInternalId = 49, sourceEntry = "GolemDexEntry"},
    {dex = 77, species = "ponyta", name = "PONYTA", sourceName = "PONYTA", category = "FIRE HORSE", heightFeet = 3, heightInches = 3, weightTenthsLb = 660, lines = {"Its hooves are 10", "times harder than", "diamonds. It can", "", "trample anything", "completely flat", "in little time"}, sourceInternalId = 163, sourceEntry = "PonytaDexEntry"},
    {dex = 78, species = "rapidash", name = "RAPIDASH", sourceName = "RAPIDASH", category = "FIRE HORSE", heightFeet = 5, heightInches = 7, weightTenthsLb = 2090, lines = {"Very competitive,", "this POKEMON will", "chase anything", "", "that moves fast", "in the hopes of", "racing it"}, sourceInternalId = 164, sourceEntry = "RapidashDexEntry"},
    {dex = 79, species = "slowpoke", name = "SLOWPOKE", sourceName = "SLOWPOKE", category = "DOPEY", heightFeet = 3, heightInches = 11, weightTenthsLb = 790, lines = {"Incredibly slow", "and dopey. It", "takes 5 seconds", "", "for it to feel", "pain when under", "attack"}, sourceInternalId = 37, sourceEntry = "SlowpokeDexEntry"},
    {dex = 80, species = "slowbro", name = "SLOWBRO", sourceName = "SLOWBRO", category = "HERMITCRAB", heightFeet = 5, heightInches = 3, weightTenthsLb = 1730, lines = {"The SHELLDER that", "is latched onto", "SLOWPOKE's tail", "", "is said to feed", "on the host's left", "over scraps"}, sourceInternalId = 8, sourceEntry = "SlowbroDexEntry"},
    {dex = 81, species = "magnemite", name = "MAGNEMITE", sourceName = "MAGNEMITE", category = "MAGNET", heightFeet = 1, heightInches = 0, weightTenthsLb = 130, lines = {"Uses anti-gravity", "to stay suspended.", "Appears without", "", "warning and uses", "THUNDER WAVE and", "similar moves"}, sourceInternalId = 173, sourceEntry = "MagnemiteDexEntry"},
    {dex = 82, species = "magneton", name = "MAGNETON", sourceName = "MAGNETON", category = "MAGNET", heightFeet = 3, heightInches = 3, weightTenthsLb = 1320, lines = {"Formed by several", "MAGNEMITEs linked", "together. They", "", "frequently appear", "when sunspots", "flare up"}, sourceInternalId = 54, sourceEntry = "MagnetonDexEntry"},
    {dex = 83, species = "farfetchd", name = "FARFETCH'D", sourceName = "FARFETCH'D", category = "WILD DUCK", heightFeet = 2, heightInches = 7, weightTenthsLb = 330, lines = {"The sprig of", "green onions it", "holds is its", "", "weapon. It is", "used much like a", "metal sword"}, sourceInternalId = 64, sourceEntry = "FarfetchdDexEntry"},
    {dex = 84, species = "doduo", name = "DODUO", sourceName = "DODUO", category = "TWIN BIRD", heightFeet = 4, heightInches = 7, weightTenthsLb = 860, lines = {"A bird that makes", "up for its poor", "flying with its", "", "fast foot speed.", "Leaves giant", "footprints"}, sourceInternalId = 70, sourceEntry = "DoduoDexEntry"},
    {dex = 85, species = "dodrio", name = "DODRIO", sourceName = "DODRIO", category = "TRIPLEBIRD", heightFeet = 5, heightInches = 11, weightTenthsLb = 1880, lines = {"Uses its three", "brains to execute", "complex plans.", "", "While two heads", "sleep, one head", "stays awake"}, sourceInternalId = 116, sourceEntry = "DodrioDexEntry"},
    {dex = 86, species = "seel", name = "SEEL", sourceName = "SEEL", category = "SEA LION", heightFeet = 3, heightInches = 7, weightTenthsLb = 1980, lines = {"The protruding", "horn on its head", "is very hard.", "", "It is used for", "bashing through", "thick ice"}, sourceInternalId = 58, sourceEntry = "SeelDexEntry"},
    {dex = 87, species = "dewgong", name = "DEWGONG", sourceName = "DEWGONG", category = "SEA LION", heightFeet = 5, heightInches = 7, weightTenthsLb = 2650, lines = {"Stores thermal", "energy in its", "body. Swims at a", "", "steady 8 knots", "even in intensely", "cold waters"}, sourceInternalId = 120, sourceEntry = "DewgongDexEntry"},
    {dex = 88, species = "grimer", name = "GRIMER", sourceName = "GRIMER", category = "SLUDGE", heightFeet = 2, heightInches = 11, weightTenthsLb = 660, lines = {"Appears in filthy", "areas. Thrives by", "sucking up", "", "polluted sludge", "that is pumped", "out of factories"}, sourceInternalId = 13, sourceEntry = "GrimerDexEntry"},
    {dex = 89, species = "muk", name = "MUK", sourceName = "MUK", category = "SLUDGE", heightFeet = 3, heightInches = 11, weightTenthsLb = 660, lines = {"Thickly covered", "with a filthy,", "vile sludge. It", "", "is so toxic, even", "its footprints", "contain poison"}, sourceInternalId = 136, sourceEntry = "MukDexEntry"},
    {dex = 90, species = "shellder", name = "SHELLDER", sourceName = "SHELLDER", category = "BIVALVE", heightFeet = 1, heightInches = 0, weightTenthsLb = 90, lines = {"Its hard shell", "repels any kind", "of attack.", "", "It is vulnerable", "only when its", "shell is open"}, sourceInternalId = 23, sourceEntry = "ShellderDexEntry"},
    {dex = 91, species = "cloyster", name = "CLOYSTER", sourceName = "CLOYSTER", category = "BIVALVE", heightFeet = 4, heightInches = 11, weightTenthsLb = 2920, lines = {"When attacked, it", "launches its", "horns in quick", "", "volleys. Its", "innards have", "never been seen"}, sourceInternalId = 139, sourceEntry = "CloysterDexEntry"},
    {dex = 92, species = "gastly", name = "GASTLY", sourceName = "GASTLY", category = "GAS", heightFeet = 4, heightInches = 3, weightTenthsLb = 2, lines = {"Almost invisible,", "this gaseous", "POKEMON cloaks", "", "the target and", "puts it to sleep", "without notice"}, sourceInternalId = 25, sourceEntry = "GastlyDexEntry"},
    {dex = 93, species = "haunter", name = "HAUNTER", sourceName = "HAUNTER", category = "GAS", heightFeet = 5, heightInches = 3, weightTenthsLb = 2, lines = {"Because of its", "ability to slip", "through block", "", "walls, it is said", "to be from an-", "other dimension"}, sourceInternalId = 147, sourceEntry = "HaunterDexEntry"},
    {dex = 94, species = "gengar", name = "GENGAR", sourceName = "GENGAR", category = "SHADOW", heightFeet = 4, heightInches = 11, weightTenthsLb = 890, lines = {"Under a full moon,", "this POKEMON", "likes to mimic", "", "the shadows of", "people and laugh", "at their fright"}, sourceInternalId = 14, sourceEntry = "GengarDexEntry"},
    {dex = 95, species = "onix", name = "ONIX", sourceName = "ONIX", category = "ROCK SNAKE", heightFeet = 28, heightInches = 10, weightTenthsLb = 4630, lines = {"As it grows, the", "stone portions of", "its body harden", "", "to become similar", "to a diamond, but", "colored black"}, sourceInternalId = 34, sourceEntry = "OnixDexEntry"},
    {dex = 96, species = "drowzee", name = "DROWZEE", sourceName = "DROWZEE", category = "HYPNOSIS", heightFeet = 3, heightInches = 3, weightTenthsLb = 710, lines = {"Puts enemies to", "sleep then eats", "their dreams.", "", "Occasionally gets", "sick from eating", "bad dreams"}, sourceInternalId = 48, sourceEntry = "DrowzeeDexEntry"},
    {dex = 97, species = "hypno", name = "HYPNO", sourceName = "HYPNO", category = "HYPNOSIS", heightFeet = 5, heightInches = 3, weightTenthsLb = 1670, lines = {"When it locks eyes", "with an enemy, it", "will use a mix of", "", "PSI moves such as", "HYPNOSIS and", "CONFUSION"}, sourceInternalId = 129, sourceEntry = "HypnoDexEntry"},
    {dex = 98, species = "krabby", name = "KRABBY", sourceName = "KRABBY", category = "RIVER CRAB", heightFeet = 1, heightInches = 4, weightTenthsLb = 140, lines = {"Its pincers are", "not only powerful", "weapons, they are", "", "used for balance", "when walking", "sideways"}, sourceInternalId = 78, sourceEntry = "KrabbyDexEntry"},
    {dex = 99, species = "kingler", name = "KINGLER", sourceName = "KINGLER", category = "PINCER", heightFeet = 4, heightInches = 3, weightTenthsLb = 1320, lines = {"The large pincer", "has 10000 hp of", "crushing power.", "", "However, its huge", "size makes it", "unwieldy to use"}, sourceInternalId = 138, sourceEntry = "KinglerDexEntry"},
    {dex = 100, species = "voltorb", name = "VOLTORB", sourceName = "VOLTORB", category = "BALL", heightFeet = 1, heightInches = 8, weightTenthsLb = 230, lines = {"Usually found in", "power plants.", "Easily mistaken", "", "for a POKE BALL,", "they have zapped", "many people"}, sourceInternalId = 6, sourceEntry = "VoltorbDexEntry"},
    {dex = 101, species = "electrode", name = "ELECTRODE", sourceName = "ELECTRODE", category = "BALL", heightFeet = 3, heightInches = 11, weightTenthsLb = 1470, lines = {"It stores electric", "energy under very", "high pressure.", "", "It often explodes", "with little or no", "provocation"}, sourceInternalId = 141, sourceEntry = "ElectrodeDexEntry"},
    {dex = 102, species = "exeggcute", name = "EXEGGCUTE", sourceName = "EXEGGCUTE", category = "EGG", heightFeet = 1, heightInches = 4, weightTenthsLb = 60, lines = {"Often mistaken", "for eggs.", "When disturbed,", "", "they quickly", "gather and attack", "in swarms"}, sourceInternalId = 12, sourceEntry = "ExeggcuteDexEntry"},
    {dex = 103, species = "exeggutor", name = "EXEGGUTOR", sourceName = "EXEGGUTOR", category = "COCONUT", heightFeet = 6, heightInches = 7, weightTenthsLb = 2650, lines = {"Legend has it that", "on rare occasions,", "one of its heads", "", "will drop off and", "continue on as an", "EXEGGCUTE"}, sourceInternalId = 10, sourceEntry = "ExeggutorDexEntry"},
    {dex = 104, species = "cubone", name = "CUBONE", sourceName = "CUBONE", category = "LONELY", heightFeet = 1, heightInches = 4, weightTenthsLb = 140, lines = {"Because it never", "removes its skull", "helmet, no one", "", "has ever seen", "this POKEMON's", "real face"}, sourceInternalId = 17, sourceEntry = "CuboneDexEntry"},
    {dex = 105, species = "marowak", name = "MAROWAK", sourceName = "MAROWAK", category = "BONEKEEPER", heightFeet = 3, heightInches = 3, weightTenthsLb = 990, lines = {"The bone it holds", "is its key weapon.", "It throws the", "", "bone skillfully", "like a boomerang", "to KO targets"}, sourceInternalId = 145, sourceEntry = "MarowakDexEntry"},
    {dex = 106, species = "hitmonlee", name = "HITMONLEE", sourceName = "HITMONLEE", category = "KICKING", heightFeet = 4, heightInches = 11, weightTenthsLb = 1100, lines = {"When in a hurry,", "its legs lengthen", "progressively.", "", "It runs smoothly", "with extra long,", "loping strides"}, sourceInternalId = 43, sourceEntry = "HitmonleeDexEntry"},
    {dex = 107, species = "hitmonchan", name = "HITMONCHAN", sourceName = "HITMONCHAN", category = "PUNCHING", heightFeet = 4, heightInches = 7, weightTenthsLb = 1110, lines = {"While apparently", "doing nothing, it", "fires punches in", "", "lightning fast", "volleys that are", "impossible to see"}, sourceInternalId = 44, sourceEntry = "HitmonchanDexEntry"},
    {dex = 108, species = "lickitung", name = "LICKITUNG", sourceName = "LICKITUNG", category = "LICKING", heightFeet = 3, heightInches = 11, weightTenthsLb = 1440, lines = {"Its tongue can be", "extended like a", "chameleon's. It", "", "leaves a tingling", "sensation when it", "licks enemies"}, sourceInternalId = 11, sourceEntry = "LickitungDexEntry"},
    {dex = 109, species = "koffing", name = "KOFFING", sourceName = "KOFFING", category = "POISON GAS", heightFeet = 2, heightInches = 0, weightTenthsLb = 20, lines = {"Because it stores", "several kinds of", "toxic gases in", "", "its body, it is", "prone to exploding", "without warning"}, sourceInternalId = 55, sourceEntry = "KoffingDexEntry"},
    {dex = 110, species = "weezing", name = "WEEZING", sourceName = "WEEZING", category = "POISON GAS", heightFeet = 3, heightInches = 11, weightTenthsLb = 210, lines = {"Where two kinds", "of poison gases", "meet, 2 KOFFINGs", "", "can fuse into a", "WEEZING over many", "years"}, sourceInternalId = 143, sourceEntry = "WeezingDexEntry"},
    {dex = 111, species = "rhyhorn", name = "RHYHORN", sourceName = "RHYHORN", category = "SPIKES", heightFeet = 3, heightInches = 3, weightTenthsLb = 2540, lines = {"Its massive bones", "are 1000 times", "harder than human", "", "bones. It can", "easily knock a", "trailer flying"}, sourceInternalId = 18, sourceEntry = "RhyhornDexEntry"},
    {dex = 112, species = "rhydon", name = "RHYDON", sourceName = "RHYDON", category = "DRILL", heightFeet = 6, heightInches = 3, weightTenthsLb = 2650, lines = {"Protected by an", "armor-like hide,", "it is capable of", "", "living in molten", "lava of 3,600", "degrees"}, sourceInternalId = 1, sourceEntry = "RhydonDexEntry"},
    {dex = 113, species = "chansey", name = "CHANSEY", sourceName = "CHANSEY", category = "EGG", heightFeet = 3, heightInches = 7, weightTenthsLb = 760, lines = {"A rare and elusive", "POKEMON that is", "said to bring", "", "happiness to those", "who manage to get", "it"}, sourceInternalId = 40, sourceEntry = "ChanseyDexEntry"},
    {dex = 114, species = "tangela", name = "TANGELA", sourceName = "TANGELA", category = "VINE", heightFeet = 3, heightInches = 3, weightTenthsLb = 770, lines = {"The whole body is", "swathed with wide", "vines that are", "", "similar to sea-", "weed. Its vines", "shake as it walks"}, sourceInternalId = 30, sourceEntry = "TangelaDexEntry"},
    {dex = 115, species = "kangaskhan", name = "KANGASKHAN", sourceName = "KANGASKHAN", category = "PARENT", heightFeet = 7, heightInches = 3, weightTenthsLb = 1760, lines = {"The infant rarely", "ventures out of", "its mother's", "", "protective pouch", "until it is 3", "years old"}, sourceInternalId = 2, sourceEntry = "KangaskhanDexEntry"},
    {dex = 116, species = "horsea", name = "HORSEA", sourceName = "HORSEA", category = "DRAGON", heightFeet = 1, heightInches = 4, weightTenthsLb = 180, lines = {"Known to shoot", "down flying bugs", "with precision", "", "blasts of ink", "from the surface", "of the water"}, sourceInternalId = 92, sourceEntry = "HorseaDexEntry"},
    {dex = 117, species = "seadra", name = "SEADRA", sourceName = "SEADRA", category = "DRAGON", heightFeet = 3, heightInches = 11, weightTenthsLb = 550, lines = {"Capable of swim-", "ming backwards by", "rapidly flapping", "", "its wing-like", "pectoral fins and", "stout tail"}, sourceInternalId = 93, sourceEntry = "SeadraDexEntry"},
    {dex = 118, species = "goldeen", name = "GOLDEEN", sourceName = "GOLDEEN", category = "GOLDFISH", heightFeet = 2, heightInches = 0, weightTenthsLb = 330, lines = {"Its tail fin", "billows like an", "elegant ballroom", "", "dress, giving it", "the nickname of", "the Water Queen"}, sourceInternalId = 157, sourceEntry = "GoldeenDexEntry"},
    {dex = 119, species = "seaking", name = "SEAKING", sourceName = "SEAKING", category = "GOLDFISH", heightFeet = 4, heightInches = 3, weightTenthsLb = 860, lines = {"In the autumn", "spawning season,", "they can be seen", "", "swimming power-", "fully up rivers", "and creeks"}, sourceInternalId = 158, sourceEntry = "SeakingDexEntry"},
    {dex = 120, species = "staryu", name = "STARYU", sourceName = "STARYU", category = "STARSHAPE", heightFeet = 2, heightInches = 7, weightTenthsLb = 760, lines = {"An enigmatic", "POKEMON that can", "effortlessly", "", "regenerate any", "appendage it", "loses in battle"}, sourceInternalId = 27, sourceEntry = "StaryuDexEntry"},
    {dex = 121, species = "starmie", name = "STARMIE", sourceName = "STARMIE", category = "MYSTERIOUS", heightFeet = 3, heightInches = 7, weightTenthsLb = 1760, lines = {"Its central core", "glows with the", "seven colors of", "", "the rainbow. Some", "people value the", "core as a gem"}, sourceInternalId = 152, sourceEntry = "StarmieDexEntry"},
    {dex = 122, species = "mr", name = "MR. MIME", sourceName = "MR.MIME", category = "BARRIER", heightFeet = 4, heightInches = 3, weightTenthsLb = 1200, lines = {"If interrupted", "while it is", "miming, it will", "", "slap around the", "offender with its", "broad hands"}, sourceInternalId = 42, sourceEntry = "MrMimeDexEntry"},
    {dex = 123, species = "scyther", name = "SCYTHER", sourceName = "SCYTHER", category = "MANTIS", heightFeet = 4, heightInches = 11, weightTenthsLb = 1230, lines = {"With ninja-like", "agility and speed,", "it can create the", "", "illusion that", "there is more", "than one"}, sourceInternalId = 26, sourceEntry = "ScytherDexEntry"},
    {dex = 124, species = "jynx", name = "JYNX", sourceName = "JYNX", category = "HUMANSHAPE", heightFeet = 4, heightInches = 7, weightTenthsLb = 900, lines = {"It seductively", "wiggles its hips", "as it walks. It", "", "can cause people", "to dance in", "unison with it"}, sourceInternalId = 72, sourceEntry = "JynxDexEntry"},
    {dex = 125, species = "electabuzz", name = "ELECTABUZZ", sourceName = "ELECTABUZZ", category = "ELECTRIC", heightFeet = 3, heightInches = 7, weightTenthsLb = 660, lines = {"Normally found", "near power plants,", "they can wander", "", "away and cause", "major blackouts", "in cities"}, sourceInternalId = 53, sourceEntry = "ElectabuzzDexEntry"},
    {dex = 126, species = "magmar", name = "MAGMAR", sourceName = "MAGMAR", category = "SPITFIRE", heightFeet = 4, heightInches = 3, weightTenthsLb = 980, lines = {"Its body always", "burns with an", "orange glow that", "", "enables it to", "hide perfectly", "among flames"}, sourceInternalId = 51, sourceEntry = "MagmarDexEntry"},
    {dex = 127, species = "pinsir", name = "PINSIR", sourceName = "PINSIR", category = "STAGBEETLE", heightFeet = 4, heightInches = 11, weightTenthsLb = 1210, lines = {"If it fails to", "crush the victim", "in its pincers,", "", "it will swing it", "around and toss", "it hard"}, sourceInternalId = 29, sourceEntry = "PinsirDexEntry"},
    {dex = 128, species = "tauros", name = "TAUROS", sourceName = "TAUROS", category = "WILD BULL", heightFeet = 4, heightInches = 7, weightTenthsLb = 1950, lines = {"When it targets", "an enemy, it", "charges furiously", "", "while whipping its", "body with its", "long tails"}, sourceInternalId = 60, sourceEntry = "TaurosDexEntry"},
    {dex = 129, species = "magikarp", name = "MAGIKARP", sourceName = "MAGIKARP", category = "FISH", heightFeet = 2, heightInches = 11, weightTenthsLb = 220, lines = {"In the distant", "past, it was", "somewhat stronger", "", "than the horribly", "weak descendants", "that exist today"}, sourceInternalId = 133, sourceEntry = "MagikarpDexEntry"},
    {dex = 130, species = "gyarados", name = "GYARADOS", sourceName = "GYARADOS", category = "ATROCIOUS", heightFeet = 21, heightInches = 4, weightTenthsLb = 5180, lines = {"Rarely seen in", "the wild. Huge", "and vicious, it", "", "is capable of", "destroying entire", "cities in a rage"}, sourceInternalId = 22, sourceEntry = "GyaradosDexEntry"},
    {dex = 131, species = "lapras", name = "LAPRAS", sourceName = "LAPRAS", category = "TRANSPORT", heightFeet = 8, heightInches = 2, weightTenthsLb = 4850, lines = {"A POKEMON that", "has been over-", "hunted almost to", "", "extinction. It", "can ferry people", "across the water"}, sourceInternalId = 19, sourceEntry = "LaprasDexEntry"},
    {dex = 132, species = "ditto", name = "DITTO", sourceName = "DITTO", category = "TRANSFORM", heightFeet = 1, heightInches = 0, weightTenthsLb = 90, lines = {"Capable of copying", "an enemy's genetic", "code to instantly", "", "transform itself", "into a duplicate", "of the enemy"}, sourceInternalId = 76, sourceEntry = "DittoDexEntry"},
    {dex = 133, species = "eevee", name = "EEVEE", sourceName = "EEVEE", category = "EVOLUTION", heightFeet = 1, heightInches = 0, weightTenthsLb = 140, lines = {"Its genetic code", "is irregular.", "It may mutate if", "", "it is exposed to", "radiation from", "element STONEs"}, sourceInternalId = 102, sourceEntry = "EeveeDexEntry"},
    {dex = 134, species = "vaporeon", name = "VAPOREON", sourceName = "VAPOREON", category = "BUBBLE JET", heightFeet = 3, heightInches = 3, weightTenthsLb = 640, lines = {"Lives close to", "water. Its long", "tail is ridged", "", "with a fin which", "is often mistaken", "for a mermaid's"}, sourceInternalId = 105, sourceEntry = "VaporeonDexEntry"},
    {dex = 135, species = "jolteon", name = "JOLTEON", sourceName = "JOLTEON", category = "LIGHTNING", heightFeet = 2, heightInches = 7, weightTenthsLb = 540, lines = {"It accumulates", "negative ions in", "the atmosphere to", "", "blast out 10000-", "volt lightning", "bolts"}, sourceInternalId = 104, sourceEntry = "JolteonDexEntry"},
    {dex = 136, species = "flareon", name = "FLAREON", sourceName = "FLAREON", category = "FLAME", heightFeet = 2, heightInches = 11, weightTenthsLb = 550, lines = {"When storing", "thermal energy in", "its body, its", "", "temperature could", "soar to over 1600", "degrees"}, sourceInternalId = 103, sourceEntry = "FlareonDexEntry"},
    {dex = 137, species = "porygon", name = "PORYGON", sourceName = "PORYGON", category = "VIRTUAL", heightFeet = 2, heightInches = 7, weightTenthsLb = 800, lines = {"A POKEMON that", "consists entirely", "of programming", "", "code. Capable of", "moving freely in", "cyberspace"}, sourceInternalId = 170, sourceEntry = "PorygonDexEntry"},
    {dex = 138, species = "omanyte", name = "OMANYTE", sourceName = "OMANYTE", category = "SPIRAL", heightFeet = 1, heightInches = 4, weightTenthsLb = 170, lines = {"Although long", "extinct, in rare", "cases, it can be", "", "genetically", "resurrected from", "fossils"}, sourceInternalId = 98, sourceEntry = "OmanyteDexEntry"},
    {dex = 139, species = "omastar", name = "OMASTAR", sourceName = "OMASTAR", category = "SPIRAL", heightFeet = 3, heightInches = 3, weightTenthsLb = 770, lines = {"A prehistoric", "POKEMON that died", "out when its", "", "heavy shell made", "it impossible to", "catch prey"}, sourceInternalId = 99, sourceEntry = "OmastarDexEntry"},
    {dex = 140, species = "kabuto", name = "KABUTO", sourceName = "KABUTO", category = "SHELLFISH", heightFeet = 1, heightInches = 8, weightTenthsLb = 250, lines = {"A POKEMON that", "was resurrected", "from a fossil", "", "found in what was", "once the ocean", "floor eons ago"}, sourceInternalId = 90, sourceEntry = "KabutoDexEntry"},
